export function CommissionerCard(n,c){const e=n.reforms.map(n=>`<li>${n}</li>`).join(""),i=n.electionsConducted.map(n=>`<li>${n}</li>`).join(""),s=n.achievements.map(n=>`<li>${n}</li>`).join(""),t=n.facts.map(n=>`<p>💡 ${n}</p>`).join("");return`\n        <div class="cec-card" id="cec-${c}">\n            <div class="cec-card-header">\n                <div class="cec-portrait">\n                    <img src="${n.portrait}" alt="Portrait of ${n.name}" loading="lazy" onerror="this.src='https://via.placeholder.com/150';" />\n                </div>\n                <div class="cec-title">\n                    <h3>${n.name}</h3>\n                    <p class="cec-term-label">Chief Election Commissioner</p>\n                    <p class="cec-meta"><strong>Appointment:</strong> ${n.appointmentDate}</p>\n                    <p class="cec-meta"><strong>Term End:</strong> ${n.endDate}</p>\n                    <p class="cec-meta"><strong>Tenure:</strong> ${n.tenure}</p>\n                </div>\n            </div>\n            <div class="cec-card-body">\n                <div class="cec-section">\n                    <h4>Election Reforms</h4>\n                    <ul>${e}</ul>\n                </div>\n                <div class="cec-section">\n                    <h4>Major Elections Conducted</h4>\n                    <ul>${i}</ul>\n                </div>\n                <div class="cec-section">\n                    <h4>Key Achievements</h4>\n                    <ul>${s}</ul>\n                </div>\n                <div class="cec-section cec-facts">\n                    <h4>Interesting Facts</h4>\n                    ${t}\n                </div>\n            </div>\n        </div>\n    `}